SELECT tc.CONSTRAINT_SCHEMA,tc.TABLE_NAME,tc.CONSTRAINT_NAME,cc.CHECK_CLAUSE,tc.ENFORCED FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.CONSTRAINT_SCHEMA IN ('csucampuscraft','review_schema') AND tc.CONSTRAINT_TYPE='CHECK' ORDER BY tc.CONSTRAINT_SCHEMA,tc.TABLE_NAME,tc.CONSTRAINT_NAME;